import { readFileSync, writeFileSync } from 'node:fs';

const catalog = JSON.parse(
  readFileSync(new URL('../frontend/lib/openflare/attack-rule-catalog.generated.json', import.meta.url), 'utf8'),
);
const rows = [];
for (let i = 0; i < catalog.rules.length; i += 10) {
  rows.push(`\t${catalog.rules.slice(i, i + 10).map(({ id }) => id).join(', ')},`);
}
const output = `// Copyright 2026 Arctel.net
// SPDX-License-Identifier: Apache-2.0

// Code generated by scripts/generate-attack-rule-ids.mjs. DO NOT EDIT.

package waf

var attackRuleIDs = []uint32{
${rows.join('\n')}
}
`;
const target = new URL('../internal/apps/openflare/waf/attack_rule_ids_generated.go', import.meta.url);
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== output) {
    throw new Error('Run node scripts/generate-attack-rule-ids.mjs to sync attack rule IDs.');
  }
} else {
  writeFileSync(target, output);
}
